UPDATE companies SET description='Tesla BioHealing Center is headquartered in Milford, Delaware, and operates wellness centers in Arizona, Florida, Illinois, and Pennsylvania. The company''s founding year and ownership structure are not publicly disclosed.

The company designs and sells a line of biophoton energy devices marketed for general wellness. Its product range includes the Biophotonizer series (models A, Alpha, M, C, and P for pets), the QiRenew System, Cornerstone System, Water Energizing System, and accessories such as the Biophoton Pillow, Energized Neck Pillow, Energized Eye Mask, Energized Spring Water, and the PawRenew Pet Bed. Tesla BioHealing also operates physical centers where customers can experience the technology. The company claims 50,000 users worldwide.

Tesla BioHealing differentiates itself with a "three-year biophoton output guarantee" promising free replacement if a device falls below minimum output, free ground shipping on U.S. orders over $600, and a "always on, no cords, no charging" ambient wellness concept. The company emphasizes that its products are not medical devices and are intended only for general wellness, relaxation, and comfort.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Wellness center services", "Biophoton device retail", "Product warranty program"], "industries": ["Wellness", "Health and wellness", "Pet care"], "materials": [], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Three-year biophoton output guarantee with free replacement", "Free ground shipping on U.S. orders over $600", "Ambient wellness: continuous field, no cords or charging required", "50,000 users worldwide", "Physical wellness centers in five states"], "facts_used": ["Headquarters in Milford, Delaware -> db", "Wellness centers in Arizona, Florida, Illinois, Pennsylvania -> /", "Product line includes Biophotonizer series, QiRenew System, Cornerstone System, Water Energizing System, Biophoton Pillow, Energized Neck Pillow, Energized Eye Mask, Energized Spring Water, PawRenew Pet Bed -> /", "Claims 50,000 users worldwide -> /", "Three-year biophoton output guarantee with free replacement -> /", "Free ground shipping on U.S. orders over $600 -> /", "Products marketed for general wellness, not medical use -> /", "Japanese language support indicated -> /"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "Shop Products\nBiophotonizers\nBiophoton Systems\nBiophoton Products & More", "founded_year": "", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": ["English", "Japanese"], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='tesla-biohealing-center' AND approved AND profile IS NULL;
UPDATE companies SET description='Teton Valley Brands operates a state-of-the-art manufacturing facility in Caldwell, Idaho, just west of Boise. The company produces all-natural potato chips made from 100% Real Idaho® potatoes, sourced from Idaho farms. Founded on the principle of simple ingredients, the brand emphasizes chips free of artificial colors, flavors, preservatives, hydrogenated oils, and refined salts.

The facility currently employs ten community members and produces both Real Idaho® Potato Chips and Tallow & Stone tortilla chips. The potato chips are crafted using hand-selected Idaho potatoes from partner Cranney Farms, a multi-generational operation homesteaded in 1907. The tortilla chips are cooked in traditional tallow, offering a clean-label snacking option with a sturdy texture for dipping.

Products are sold through retail locations across Idaho’s Treasure Valley, including branded varieties created in partnership with Boise State Athletics and the University of Idaho Athletics. The company serves the snack food and retail grocery sectors, with a focus on regional distribution and collegiate licensing.

Teton Valley Brands differentiates itself by keeping the entire production process in Idaho, from potato sourcing to manufacturing and shipping. The partnership with Cranney Farms ensures a consistent supply of potatoes grown in volcanic soil with warm days and cool nights, which the company credits for superior taste and texture.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Potato chip manufacturing", "Tortilla chip manufacturing", "Seasoning and flavoring", "Packaging"], "industries": ["Snack food", "Retail grocery", "Collegiate athletics licensing"], "materials": ["Idaho potatoes", "Tallow"], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["All-natural chips with no artificial colors, flavors, preservatives, hydrogenated oils, or refined salts", "Made from 100% Real Idaho\u00ae potatoes sourced from Idaho farms", "Tortilla chips cooked in traditional tallow for clean flavor", "Partnership with multi-generational Idaho potato farmers (Cranney Farms)", "Licensed chips for Boise State and University of Idaho athletics"], "facts_used": ["Headquarters in Caldwell, Idaho -> /", "State-of-the-art manufacturing facility -> /", "Employs ten community members -> /", "Produces Real Idaho\u00ae Potato Chips and Tallow & Stone tortilla chips -> /", "Uses 100% Real Idaho\u00ae potatoes from Idaho farms -> /", "Primary potato supplier: Cranney Farms (homesteaded 1907, 20,000 acres) -> /", "Chips are gluten-free, non-GMO, no artificial preservatives -> /", "Partnership with Boise State Athletics and University of Idaho Athletics for branded chips -> /", "Products sold at retail locations across Treasure Valley -> /"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "Our state of the art manufacturing facility is located just west of Boise, in Caldwell, ID.", "founded_year": "", "employee_count": "10", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership